effect.shader:
void main(){
    vec2 px = thickness / acScreenSize;
    float a0 = texture2DCv(inputImg.texture, acScreenNorm).a;
    float ax = texture2DCv(inputImg.texture, acScreenNorm + vec2(px.x,0.0)).a;
    float ay = texture2DCv(inputImg.texture, acScreenNorm + vec2(0.0,px.y)).a;
    float axn= texture2DCv(inputImg.texture, acScreenNorm - vec2(px.x,0.0)).a;
    float ayn= texture2DCv(inputImg.texture, acScreenNorm - vec2(0.0,px.y)).a;
    float edge = abs(ax-axn) + abs(ay-ayn) + abs(ax-a0) + abs(ay-a0);
    edge = clamp(edge*intensity, 0.0, 1.0);
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec4 glow = vec4(color.rgb, 1.0) * edge;
    vec4 base = src * keepImage;
    gl_FragColor = base + glow - base*glow.a;
}
